#[path="../sdk/widgets.rs"]mod widgets;
use widgets::*;
#[test]fn button_capture_release_and_reset(){let mut b=Button::new(Rect::new(10,10,80,24));assert!(!b.pointer(20,20,1));assert!(b.pressed);assert!(!b.pointer(100,20,0));assert!(!b.pointer(0,0,1));assert!(!b.pointer(20,20,0));assert!(!b.pointer(20,20,1));assert!(b.pointer(20,20,0));b.pointer(20,20,1);b.reset(1);assert!(!b.pointer(20,20,0));}
#[test]fn field_selection_cursor_and_atomic_capacity(){let mut t=TextInput::<8>::new();assert!(t.set(b"abcde"));t.key(0x104);t.key(0x103|(1<<16));t.key(0x103|(1<<16));assert_eq!(t.range(),(0,2));assert!(t.insert(b"X"));assert_eq!(&t.bytes[..t.len],b"Xcde");t.key(0x106);assert_eq!(&t.bytes[..t.len],b"Xde");t.key((1<<17)|b'A' as u32);assert!(t.insert(b"12345678"));assert!(!t.insert(b"9"));assert_eq!(&t.bytes[..t.len],b"12345678");assert!(!t.insert(b"\n"));t.key(8);assert_eq!(&t.bytes[..t.len],b"1234567");}
#[test]fn scrollbar_empty_page_click_drag_and_bounds(){let mut s=Scrollbar::new(Rect::new(0,0,16,200));s.range(0,25);s.pointer(8,190,1);assert_eq!(s.value,0);s.pointer(8,190,0);s.range(64,25);assert!(s.pointer(8,190,1));assert_eq!(s.value,1);s.pointer(8,190,0);s.pointer(8,175,1);assert_eq!(s.value,26);s.pointer(8,175,0);let thumb=s.thumb();s.pointer(8,thumb.y+2,1);s.pointer(900,999,1);assert_eq!(s.value,64);s.pointer(-10,-10,1);assert_eq!(s.value,0);s.reset(0);assert!(!s.dragging());s.range(3,25);assert!(s.value<=3);}
